//! Differential tests for the online-mode cryptography.
//!
//! Fixtures under `tests/` were generated with Java 21 + JCE (the same
//! libraries vanilla uses): `KeyPairGenerator`, `Cipher("RSA/ECB/PKCS1Padding")`,
//! `Cipher("AES/CFB8/NoPadding")`, `MessageDigest("SHA-1")`, and
//! `BigInteger.toString(16)`. See `DECISIONS.md` for the exact oracle script.

use folia_core::crypto::{
    AES_KEY_SIZE, Aes128, Cfb8, RsaKeyPair, RsaPublicKey, Sha1, constant_time_eq, java_bigint_hex,
    random_bytes, server_hash, sha1,
};

