const RSA_SPKI_BASE64: &str = "MIGfMA0GCSqGSIb3DQEBAQUAA4GNADCBiQKBgQCz2yyPq9oVcogjaQ4XEW4o0M+gbRt/DKa+thgAAHtx6g3lXQtnNdKwoE/3MbKWbQAkMGV/7G+7RyksScVoL8EyKslI/XDFZ9ziISwkf1pcDAHYTkoFgtEOlcQXA3yLs6EvD9qUkBR1bAJ+hWbumVsA/yikZv8BBfj2XkP8oHzg6wIDAQAB";
const SECRET_HEX: &str = "0102030405060708090a0b0c0d0e0f10";
// Java: Cipher("RSA/ECB/PKCS1Padding").doFinal(secret).
const SECRET_CIPHERTEXT_BASE64: &str = "ip9DAyEnJcw66ryrfLarMILw6fFkxL54066Q3W7LrcEz9zPjhMOx8NHdnaGtatbElAVvq/E2EnRRDKGIpw+5MFi9Jy+8hoMKrzStMmsQI9p2FmaDoGmCQA/cVQnzPeTM27sG7K4ftFP9vBhH2kpX+cHfhsZu5s4SHw9uzG1CGW0=";
const TOKEN_CIPHERTEXT_BASE64: &str = "qXIz9taXlDyWvsSe+qBPtFAyG2+Df+12r6fxqlYxQ5QRFdZ1GGACZpvnKlBz6WRBb5OcN7+aP7By7Dx9HdHk6IryrE4T4YDhTwdQSGNtSuZaQGZOEQIrzHBbj8OQSewZIPYje+aaUrJJTOV61lgQUfkPSLvarxEmF2Zbc/v7T9I=";
// Java: raw RSA of a hand-built PKCS#1 block 00 02 01 02 .. 0x81 00 secret.
const SECRET_CIPHERTEXT_FIXED_BASE64: &str = "YEZIdr5U++89C6TfdPWTpwTrTRywpIxzPIUA8Vvy9ExAcCN/fp00hUDN701HYo0smamXk+yQnBZrgDQaIEjKWi9od9byffXokjLjbfqr3vZjvdkjQo0xjG0IHk0JJWleh0JccQtdGOJ/Fxgzh0A3pXrGF2kk8qZkGQeC+Lh/8XA=";

fn decode_hex(value: &str) -> Vec<u8> {
    assert_eq!(value.len() % 2, 0, "odd hex length");
    (0..value.len())
        .step_by(2)
        .map(|index| u8::from_str_radix(&value[index..index + 2], 16).unwrap())
        .collect()
}

fn encode_hex(bytes: &[u8]) -> String {
    bytes.iter().map(|byte| format!("{byte:02x}")).collect()
}

fn decode_base64(value: &str) -> Vec<u8> {
    const ALPHABET: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut output = Vec::new();
    let mut accumulator = 0u32;
    let mut bits = 0u32;
    for byte in value.bytes() {
        if byte == b'=' || byte.is_ascii_whitespace() {
            continue;
        }
        let Some(index) = ALPHABET.iter().position(|candidate| *candidate == byte) else {
            panic!("invalid base64 byte {byte}");
        };
        accumulator = (accumulator << 6) | index as u32;
        bits += 6;
        if bits >= 8 {
            bits -= 8;
            output.push((accumulator >> bits) as u8);
        }
    }
    output
}

fn fixture_keypair() -> RsaKeyPair {
    RsaKeyPair::from_components(&decode_hex(RSA_N), 65537, &decode_hex(RSA_D)).unwrap()
}

fn secret() -> [u8; AES_KEY_SIZE] {
    decode_hex(SECRET_HEX).try_into().unwrap()
}

#[test]
fn sha1_matches_fips_vectors() {
    assert_eq!(
        encode_hex(&sha1(b"")),
        "da39a3ee5e6b4b0d3255bfef95601890afd80709"
    );
    assert_eq!(
        encode_hex(&sha1(b"abc")),
        "a9993e364706816aba3e25717850c26c9cd0d89d"
    );
    assert_eq!(
        encode_hex(&sha1(
            b"abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq"
        )),
        "84983e441c3bd26ebaae4aa1f95129e5e54670f1"
    );

    // Incremental updates must produce the same digest as one call.
    let mut hasher = Sha1::new();
    hasher.update(b"abcdbcdecdefdefgefghfghighijhi");
    hasher.update(b"jkijkljklmklmnlmnomnopnopq");
    assert_eq!(
        encode_hex(&hasher.finish()),
        "84983e441c3bd26ebaae4aa1f95129e5e54670f1"
    );
}

#[test]
fn java_bigint_hex_matches_oracle_including_negatives() {
    // Java 21: new BigInteger(HexFormat.of().parseHex(x)).toString(16).
    let cases = [
        ("00", "0"),
        ("7f", "7f"),
        ("80", "-80"),
        ("ff", "-1"),
        ("0080", "80"),
        ("8000", "-8000"),
        (
            "da39a3ee5e6b4b0d3255bfef95601890afd80709",
            "-25c65c11a194b4f2cdaa40106a9fe76f5027f8f7",
        ),
        ("0000", "0"),
        ("0100", "100"),
    ];
    for (digest, expected) in cases {
        assert_eq!(java_bigint_hex(&decode_hex(digest)), expected, "{digest}");
    }
}

#[test]
fn server_hash_matches_java_crypt_digest_data() {
    // Java: SHA-1("" || secret || publicKey.getEncoded()) rendered by
    // BigInteger.toString(16).
    let keypair = fixture_keypair();
    assert_eq!(
        server_hash("", &keypair.public_key_der(), &secret()),
        "7d3d2cfa87c482a3daaa8b6e7fab52327dc4534"
    );
}

#[test]
fn aes128_fips197_block_vector() {
    let key: [u8; 16] = decode_hex("000102030405060708090a0b0c0d0e0f")
        .try_into()
        .unwrap();
    let mut block: [u8; 16] = decode_hex("00112233445566778899aabbccddeeff")
        .try_into()
        .unwrap();
    Aes128::new(&key).encrypt_block(&mut block);
    assert_eq!(encode_hex(&block), "69c4e0d86a7b0430d8cdb78070b4c55a");
}

#[test]
fn aes_cfb8_matches_nist_and_minecraft_vectors() {
    // NIST SP 800-38A F.3.7 CFB8-AES128.Encrypt.
    let key: [u8; 16] = decode_hex("2b7e151628aed2a6abf7158809cf4f3c")
        .try_into()
        .unwrap();
    let iv: [u8; 16] = decode_hex("000102030405060708090a0b0c0d0e0f")
        .try_into()
        .unwrap();
    let plaintext = decode_hex(
        "6bc1bee22e409f96e93d7e117393172aae2d8a571e03ac9c9eb76fac45af8e51\
         30c81c46a35ce411e5fbc1191a0a52eff69f2445df4f9b17ad2b417be66c3710",
    );
    let expected = decode_hex(
        "3b79424c9c0dd436bace9e0ed4586a4f32b9ded50ae3ba69d472e88267fb5052\
         70cbad1e257691f7c47c5038297edda32ff26d0ed19174096161ecc14086dd62",
    );
    let mut cipher = Cfb8::with_iv(&key, &iv, false);
    let mut encrypted = plaintext.clone();
    cipher.process(&mut encrypted);
    assert_eq!(encrypted, expected);

    let mut decrypted = encrypted;
    Cfb8::with_iv(&key, &iv, true).process(&mut decrypted);
    assert_eq!(decrypted, plaintext);

    // Minecraft's Crypt.getCipher uses IvParameterSpec(key.getEncoded()).
    let mut minecraft_style = decode_hex("000102030405060708090a0b0c0d0e0f");
    Cfb8::encryptor(&key).process(&mut minecraft_style);
    assert_eq!(
        encode_hex(&minecraft_style),
        "7fa3938dd6ad6833c12cbaa347f00f72"
    );
}

#[test]
fn cfb8_round_trips_across_arbitrary_chunk_boundaries() {
    let key: [u8; 16] = decode_hex(SECRET_HEX).try_into().unwrap();
    let plaintext: Vec<u8> = (0..=255u8).cycle().take(1000).collect();
    let mut encrypted = plaintext.clone();
    let mut encryptor = Cfb8::encryptor(&key);
    for chunk in encrypted.chunks_mut(7) {
        encryptor.process(chunk);
    }
    assert_ne!(encrypted, plaintext);

    let mut decrypted = encrypted;
    let mut decryptor = Cfb8::decryptor(&key);
    for chunk in decrypted.chunks_mut(13) {
        decryptor.process(chunk);
    }
    assert_eq!(decrypted, plaintext);
}

#[test]
fn rsa_public_key_der_matches_java_spki() {
    let keypair = fixture_keypair();
    let der = keypair.public_key_der();
    assert_eq!(der, decode_base64(RSA_SPKI_BASE64));

    let parsed = RsaPublicKey::from_der(&der).unwrap();
    assert_eq!(parsed.to_der(), der);
    assert_eq!(parsed.modulus_bytes(), 128);
    assert!(RsaPublicKey::from_der(&[0x30, 0x00]).is_err());
    assert!(RsaPublicKey::from_der(&der[..der.len() - 1]).is_err());
}

#[test]
fn rsa_decrypts_java_encrypted_secret_and_token() {
    let keypair = fixture_keypair();
    assert_eq!(
        keypair
            .decrypt_pkcs1v15(&decode_base64(SECRET_CIPHERTEXT_BASE64))
            .unwrap(),
        secret()
    );
    assert_eq!(
        keypair
            .decrypt_pkcs1v15(&decode_base64(TOKEN_CIPHERTEXT_BASE64))
            .unwrap(),
        decode_hex("11223344")
    );
    assert_eq!(
        keypair
            .decrypt_pkcs1v15(&decode_base64(SECRET_CIPHERTEXT_FIXED_BASE64))
            .unwrap(),
        secret()
    );
}

#[test]
fn rsa_round_trip_and_rejections() {
    let keypair = fixture_keypair();
    let ciphertext = keypair
        .public()
        .encrypt_pkcs1v15(b"Minecraft shared secret")
        .unwrap();
    assert_eq!(ciphertext.len(), 128);
    assert_eq!(
        keypair.decrypt_pkcs1v15(&ciphertext).unwrap(),
        b"Minecraft shared secret"
    );

    // Wrong length, out-of-range ciphertext, and garbage padding must all be
    // rejected rather than producing random plaintext.
    assert!(keypair.decrypt_pkcs1v15(&[0u8; 127]).is_err());
    assert!(keypair.decrypt_pkcs1v15(&[0xFF; 128]).is_err());
    assert!(keypair.decrypt_pkcs1v15(&[0x00; 128]).is_err());

    // Token mismatch: the constant-time comparison is the only check vanilla
    // performs for the challenge.
    let expected = [1u8, 2, 3, 4];
    assert!(!constant_time_eq(&[1u8, 2, 3, 5], &expected));
    assert!(!constant_time_eq(&[1u8, 2, 3], &expected));
    assert!(constant_time_eq(&expected, &expected));
}

#[test]
fn generated_keypair_is_usable() {
    let keypair = RsaKeyPair::generate().unwrap();
    let der = keypair.public_key_der();
    assert!(
        (160..=170).contains(&der.len()),
        "SPKI length {}",
        der.len()
    );
    let public = RsaPublicKey::from_der(&der).unwrap();

    let mut message = [0u8; 16];
    random_bytes(&mut message).unwrap();
    let ciphertext = public.encrypt_pkcs1v15(&message).unwrap();
    assert_eq!(keypair.decrypt_pkcs1v15(&ciphertext).unwrap(), message);

    // A fresh key pair must not decrypt the other key's ciphertext.
    let other = RsaKeyPair::generate().unwrap();
    assert!(other.decrypt_pkcs1v15(&ciphertext).is_err());
}
